import{c as d,Q as r,j as o,m as n}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-架构设计-补充专题","description":"","frontmatter":{"title":"架构师-备考 综合知识-架构设计-补充专题"},"headers":[],"relativePath":"综合知识/数据库/补充专题.md","filePath":"综合知识/数据库/补充专题.md","lastUpdated":null}'),s={name:"综合知识/数据库/补充专题.md"};function a(e,t,g,h,l,i){return r(),o("div",null,[...t[0]||(t[0]=[n('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] ABSD 三大基础 + 六大步骤 + 文档输出</li><li>[x] DSSA 三大基本活动 + 四角色 + 三层次模型</li><li>[x] SOA 详细特征 + ESB 角色 + 关键技术表</li><li>[x] 架构风格全景分类</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、absd-基于体系结构的软件设计-★" tabindex="-1">一、ABSD（基于体系结构的软件设计）★ <a class="header-anchor" href="#一、absd-基于体系结构的软件设计-★" aria-label="Permalink to &quot;一、ABSD（基于体系结构的软件设计）★&quot;">​</a></h3><blockquote><p>核心：<strong>架构驱动设计</strong>，由业务+质量+功能需求组合驱动，在设计过程中架构占主导中心地位。</p></blockquote><p><strong>三大基础：</strong></p><ol><li>功能分解（基于模块的内聚和耦合技术）</li><li>通过选择架构风格实现质量和业务需求</li><li>软件模板的使用</li></ol><p><strong>关键特点</strong>：需求获取和分析还没完成就开始了软件设计；递归且迭代；每一步清晰定义。</p><p><strong>六大步骤</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>说明</th></tr></thead><tbody><tr><td><strong>架构需求</strong></td><td>标识构件（生成类→抽象构件→分析产生构件）</td></tr><tr><td><strong>架构设计</strong></td><td>将需求阶段标识的构件映射成构件进行分析</td></tr><tr><td><strong>架构文档化</strong></td><td>产出两种文档：<strong>架构规格说明</strong> + 测试架构需求的质量设计说明书</td></tr><tr><td><strong>架构复审</strong></td><td>外部人员（用户代表/领域专家）参加，复审需求/质量/构件划分</td></tr><tr><td><strong>架构实现</strong></td><td>实现构件，构件组装成系统</td></tr><tr><td><strong>架构演化</strong></td><td>按需增删构件，使架构可复用</td></tr></tbody></table><p><strong>描述方式</strong>：采用<strong>视角和视图</strong>描述架构，<strong>用例</strong>描述功能需求，<strong>质量属性场景</strong>描述质量需求。</p><hr><h3 id="二、dssa-特定领域软件架构-★" tabindex="-1">二、DSSA（特定领域软件架构）★ <a class="header-anchor" href="#二、dssa-特定领域软件架构-★" aria-label="Permalink to &quot;二、DSSA（特定领域软件架构）★&quot;">​</a></h3><blockquote><p>专用于一类特定类型任务的软件构件集合，支持一个特定领域中多个应用的生成。</p></blockquote><p><strong>垂直域</strong>：特定领域中的通用完整架构。<strong>水平域</strong>：多个不同领域间相同部分的小工具（如购物和教育都有的收费系统）。</p><p><strong>三大基本活动：</strong></p><table tabindex="0"><thead><tr><th>活动</th><th>目标</th><th>内容</th></tr></thead><tbody><tr><td><strong>领域分析</strong></td><td>获得<strong>领域模型</strong>（领域需求）</td><td>识别信息源→分析共享需求→建立领域模型</td></tr><tr><td><strong>领域设计</strong></td><td>获得 <strong>DSSA</strong></td><td>领域模型的解决方案，适应多系统的高层设计</td></tr><tr><td><strong>领域实现</strong></td><td>开发和组织<strong>可重用信息</strong></td><td>从现有系统提取或新开发可重用构件</td></tr></tbody></table><p><strong>四种角色</strong>：领域专家（提供知识）→ 领域分析人员（控制分析过程）→ 领域设计人员（开发DSSA）→ 领域实现人员（开发构件）。</p><p><strong>三层次模型：</strong></p><table tabindex="0"><thead><tr><th>层次</th><th>角色</th><th>产出</th></tr></thead><tbody><tr><td><strong>领域开发环境</strong></td><td>领域架构师</td><td>参考结构、参考需求、架构、领域模型、开发工具</td></tr><tr><td><strong>领域特定应用开发环境</strong></td><td>应用工程师</td><td>根据具体环境将核心架构实例化</td></tr><tr><td><strong>应用执行环境</strong></td><td>操作员</td><td>实现实例化后的架构</td></tr></tbody></table><p><strong>建立过程</strong>（并发、递归、反复、螺旋型）：定义领域范围 → 定义领域特定元素（领域字典）→ 定义约束 → 定义领域模型和架构 → 产生可复用产品单元。</p><hr><h3 id="三、soa-面向服务的架构-★" tabindex="-1">三、SOA（面向服务的架构）★ <a class="header-anchor" href="#三、soa-面向服务的架构-★" aria-label="Permalink to &quot;三、SOA（面向服务的架构）★&quot;">​</a></h3><p><strong>特征</strong>：粗粒度、松耦合、标准化接口（WSDL）；可从企业外部访问、服务分级、可重用。</p><p><strong>演进趋势</strong>：基于对象 → 基于构件 → 基于服务 → <strong>架构越来越松散耦合，粒度越来越粗，接口越来越标准</strong>。</p><p><strong>服务构件 vs 传统构件：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>服务构件</th><th>传统构件</th></tr></thead><tbody><tr><td>粒度</td><td>粗粒度</td><td>细粒度居多</td></tr><tr><td>接口</td><td>标准 WSDL</td><td>具体 API</td></tr><tr><td>语言</td><td>无关</td><td>绑定特定语言</td></tr><tr><td>QoS</td><td>通过容器提供</td><td>程序代码直接控制</td></tr></tbody></table><p><strong>SOA 关键技术栈：</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>协议</th></tr></thead><tbody><tr><td>发现服务</td><td>UDDI、DISCO</td></tr><tr><td>描述服务</td><td>WSDL、XML Schema</td></tr><tr><td>消息格式层</td><td>SOAP、REST</td></tr><tr><td>编码格式层</td><td>XML（DOM, SAX）</td></tr><tr><td>传输协议层</td><td>HTTP、TCP/IP、SMTP</td></tr></tbody></table><p><strong>ESB（企业服务总线）</strong>：连接各服务节点的管道，集成基于不同协议的不同服务，做消息转化/解释/路由。四大能力：描述服务元数据和注册管理、传递和转换数据、发现/路由/匹配/选择、安全/质量/负载均衡。</p><p><strong>Web Service 三角色</strong>：服务提供者（发布）→ 服务注册中心（查找）→ 服务请求者（绑定）。</p><p><strong>真题速记</strong>：SOAP 用于远程调用，BPEL 用于编排组合服务。</p><hr><h3 id="四、架构风格全景分类" tabindex="-1">四、架构风格全景分类 <a class="header-anchor" href="#四、架构风格全景分类" aria-label="Permalink to &quot;四、架构风格全景分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>大类</th><th>子风格</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>数据流</strong></td><td>批处理</td><td>整体为单位，顺序执行（传统编译器）</td></tr><tr><td></td><td>管道-过滤器</td><td>线性传递，可并行</td></tr><tr><td><strong>调用/返回</strong></td><td>主程序-子程序</td><td>显式调用</td></tr><tr><td></td><td>面向对象</td><td>对象作为构件，方法调用</td></tr><tr><td></td><td>层次结构</td><td>每层最多影响上下两层（OSI 7 层）</td></tr><tr><td><strong>独立构件</strong></td><td>进程通信</td><td>消息传递，同步/异步</td></tr><tr><td></td><td>事件驱动</td><td>事件触发，不直接调用</td></tr><tr><td><strong>虚拟机</strong></td><td>解释器</td><td>解释引擎+存储区+数据结构</td></tr><tr><td></td><td>规则系统</td><td>规则集+解释器+选择器+工作内存</td></tr><tr><td><strong>仓库</strong></td><td>数据库</td><td>中央共享数据源</td></tr><tr><td></td><td>黑板</td><td>黑板+知识源+控制器（语音识别/知识推理）</td></tr><tr><td><strong>闭环</strong></td><td>过程控制</td><td>反馈循环调节参数（巡航定速/空调温控）</td></tr><tr><td><strong>C2</strong></td><td>—</td><td>连接件绑定的并行构件网络</td></tr></tbody></table><h3 id="五、rup-补充" tabindex="-1">五、RUP 补充 <a class="header-anchor" href="#五、rup-补充" aria-label="Permalink to &quot;五、RUP 补充&quot;">​</a></h3><p><strong>6+2+1 工作流</strong>：6 个开发流（业务建模→需求→分析设计→实现→测试→部署）+ 2 个管理流（配置管理+项目管理）+ 1 个环境流。</p><p><strong>4+1 视图关注者</strong>：用例视图（分析/测试人员）、逻辑视图（最终用户）、实现视图（程序员）、进程视图（集成人员）、部署视图（系统工程师）。</p>',38)])])}const S=d(s,[["render",a]]);export{b as __pageData,S as default};
